/* Step 2: Validation */
bool example_validate_fishing(ORGANIC_CREATION_REQUEST *req)
{
    /* Geography: Check for coastal areas */
    if (!validate_geography(req))
        return FALSE;  /* No coast = no fishing */

    /* Economy: Will adding fish break anything? */
    if (!validate_economy(req))
        return FALSE;  /* Too much food already? */

    /* Lore: Does fishing fit world theme? */
    if (!validate_lore(req))
        return FALSE;  /* High-tech world? No fishing */

    /* Dependencies: What else is needed? */
    req->dependencies = analyze_dependencies("fish", ORGANIC_CREATE_RESOURCE);
    /* Returns: ["fishing skill", "fishing rod item", "fisher profession",
                 "coastal fishing rooms", "fishmonger NPC", "fish recipes"] */

    return TRUE;
}

