/* Step 4: Execution */
bool example_execute_fishing_creation(void)
{
    SKILL_ECOSYSTEM *fishing = build_skill_ecosystem("fishing", find_area_by_name("Darkhaven"));

    /* Creates everything in the plan */
    /* - Adds skill to skill table */
    /* - Creates NPCs (teacher, workers, vendor) */
    /* - Generates rooms (docks, shore, market) */
    /* - Creates items (fishing rod) */
    /* - Adds resource (fish) to economy */
    /* - Adds recipes to cook profession */
    /* - Updates supply chains */

    if (create_skill_fully(fishing))
    {
        /* Announce in periodicos */
        smart_announce(
            "Fishing Industry Established in Darkhaven",
            "Thanks to the efforts of local fisherfolk, a new fishing industry "
            "has emerged in Darkhaven. Citizens can now learn fishing from the "
            "Old Fisherman at the docks.",
            EVENT_CATEGORY_ECONOMY,
            ANNOUNCE_PRIORITY_MEDIUM,
            "Darkhaven"
        );

        return TRUE;
    }

    return FALSE;
}

/* Integration with Beeler */
void beeler_autonomous_organic_creation(void)
{
    char *need = NULL;

    /* Check every ~30 minutes if world needs something */
    if (detect_economic_need("resource", &need))
    {
        /* Create the entire ecosystem for that need */
        ORGANIC_CREATION_REQUEST *req = plan_resource_creation(
            need, "Detected economic shortage", TRIGGER_WORLD_BALANCE
        );

        if (validate_creation_request(req))
        {
            /* Beeler thinks about it, then creates it */
            execute_organic_creation(req);
        }
    }

    /* Also check geographic opportunities */
    AREA_DATA *area;
    char **opportunities = NULL;
    for (area = first_area; area; area = area->next)
    {
        if (detect_geographic_opportunity(area, &opportunities))
        {
            /* Coastal area with no fishing? Add it. */
            /* Mountain area with no mining? Add it. */
            /* etc. */
        }
    }
}
